//! Writes the TypeScript wire types. Run with `--features ts`.
//!
//! The output folder comes from THEOREM_WIRE_DIR, or defaults to
//! `src/lib/workbench/wire` in the repository. Stale generated files are
//! removed first, so a deleted Rust type also disappears from the folder.
#![cfg(feature = "ts")]

use std::path::PathBuf;
use theorem_workbench_core::{
    agent::{AgentOutcome, RefusalCode},
    arrangement::ArrangementMsg,
    completion::{Completion, DelegationChangeKind},
    effect::Effect,
    host::HostMessage,
    ids::Actor,
    keys::{KeyIssue, Overrides, Shortcut},
    msg::Inbound,
    panel::Caret,
    registry::{CatalogEntry, PanelDescriptor, PickerRow, Presentation, PresentationEntry},
    semantics::{SemanticDiff, SemanticTree},
    stale::Stale,
};
use ts_rs::{Config, TS};

const HEADER: &str = "This file was generated by [ts-rs]";

fn out_dir() -> PathBuf {
    match std::env::var_os("THEOREM_WIRE_DIR") {
        Some(dir) => PathBuf::from(dir),
        None => PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../src/lib/workbench/wire"),
    }
}

#[test]
fn export_wire_types() {
    let dir = out_dir();
    std::fs::create_dir_all(&dir).unwrap();
    for entry in std::fs::read_dir(&dir).unwrap().flatten() {
        let path = entry.path();
        if path.extension().is_some_and(|e| e == "ts")
            && std::fs::read_to_string(&path).is_ok_and(|t| t.contains(HEADER))
        {
            std::fs::remove_file(path).unwrap();
        }
    }

    let cfg = Config::new().with_out_dir(&dir);
    Effect::export_all(&cfg).unwrap();
    Completion::export_all(&cfg).unwrap();
    DelegationChangeKind::export_all(&cfg).unwrap();
    HostMessage::export_all(&cfg).unwrap();
    Inbound::export_all(&cfg).unwrap();
    PanelDescriptor::export_all(&cfg).unwrap();
    PickerRow::export_all(&cfg).unwrap();
    CatalogEntry::export_all(&cfg).unwrap();
    Presentation::export_all(&cfg).unwrap();
    PresentationEntry::export_all(&cfg).unwrap();
    Overrides::export_all(&cfg).unwrap();
    KeyIssue::export_all(&cfg).unwrap();
    Shortcut::export_all(&cfg).unwrap();
    SemanticTree::export_all(&cfg).unwrap();
    SemanticDiff::export_all(&cfg).unwrap();
    Actor::export_all(&cfg).unwrap();
    AgentOutcome::export_all(&cfg).unwrap();
    RefusalCode::export_all(&cfg).unwrap();
    Stale::export_all(&cfg).unwrap();
    Caret::export_all(&cfg).unwrap();
    ArrangementMsg::export_all(&cfg).unwrap();

    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .flatten()
        .filter(|e| std::fs::read_to_string(e.path()).is_ok_and(|t| t.contains(HEADER)))
        .filter_map(|e| {
            e.path()
                .file_stem()
                .map(|s| s.to_string_lossy().into_owned())
        })
        .collect();
    names.sort();
    let index: String = names
        .iter()
        .map(|n| format!("export type {{ {n} }} from \"./{n}\";\n"))
        .collect();
    std::fs::write(
        dir.join("index.ts"),
        format!("// Generated by tests/wire_export.rs\n{index}"),
    )
    .unwrap();
}
